}"}, {"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林聆",
      "role": "protagonist",
      "identity": "前音频工程师，现末世幸存者",
      "traits": ["听力敏锐", "坚韧独立", "直觉准确", "内心柔软", "善于分析"],
      "overt_motivation": "在末世中生存下去，利用自己的听力优势帮助同伴",
      "covert_motivation": "渴望被真正理解和接纳，害怕成为他人的负担",
      "secret_fear": "担心自己的盲眼会害死保护她的人",
      "misperception_of_other": "以为沈默的摩斯密码是某种末世系统的提示音",
      "hidden_connection": "前世正是因为她的听力敏锐，才让沈默在保护她时不得不大声呼喊暴露位置"
    },
    {
      "name": "沈默",
      "role": "deuteragonist",
      "identity": "前特种部队狙击手，现末世幸存者",
      "traits": ["沉默寡言", "观察细致", "保护欲强", "内心温柔", "决断果敢"],
      "overt_motivation": "保护林聆安全，找到安全的避难所",
      "covert_motivation": "想要弥补前世的遗憾，但又害怕改变历史会让她遭遇更糟的命运",
      "secret_fear": "害怕林聆知道真相后会自责，也害怕无论怎么努力都无法改变结局",
      "misperception_of_other": "以为林聆对他的感情只是依赖和感激",
      "hidden_connection": "拥有完整的重生记忆，知道林聆前世是如何死去的，也知道自己失声的真正原因"
    }
  ],
  "supporting_characters": [
    {
      "name": "丧尸群",
      "function": "阻碍",
      "identity": "末世感染者",
      "description": "对声音极度敏感的丧尸群体，构成了录音棚外的主要威胁"
    },
    {
      "name": "录音设备",
      "function": "助力",
      "identity": "末世中的工具",
      "description": "录音棚内的专业设备，既是生存工具也是情感载体，包含着沈默三年前录制的告白"
    }
  ],
  "relationship_dynamics": "两人被困在录音棚这个封闭空间内，形成了高度依赖的关系。林聆的听力敏锐与沈默的观察力形成互补，但信息不对等造成了情感错位。沈默的重生记忆让他背负着无法言说的秘密，而林聆的误解让这份爱意更加虐心。第四天灾元素暗示他们的挣扎可能只是更高维度存在的剧本安排。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立末世世界观，介绍两位主角的特殊能力和当前困境，展示他们通过摩斯密码建立的沟通方式",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "无声的警报",
        "core_event": "林聆通过耳机听到摩斯密码警报，意识到丧尸正在接近录音棚。沈默通过手势和简单的文字与她交流，两人开始准备防御。",
        "emotional_tone": "紧张中带着默契",
        "key_scenes": ["林聆在黑暗中精准定位丧尸位置", "沈默用摩斯密码指导林聆操作设备", "两人在录音棚内布置简易防线"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "人声诱饵",
        "core_event": "为了引开远处的丧尸群，他们需要制作人声诱饵。林聆利用自己的音频专业知识，沈默提供战术建议，两人配合制作出逼真的诱饵录音。",
        "emotional_tone": "合作中的微妙情愫",
        "key_scenes": ["林聆调试音频设备展现专业能力", "沈默用手势表达赞赏", "成功引开丧尸后的短暂放松时刻"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "系统的提示",
        "core_event": "林聆开始怀疑摩斯密码并非系统提示，而是人为的。她回忆起一些模糊的既视感，但无法确定。沈默发现她的疑惑，内心挣扎是否要透露真相。",
        "emotional_tone": "困惑与隐秘的痛苦",
        "key_scenes": ["林聆独自思考摩斯密码的来源", "沈默深夜查看录音笔里的告白", "两人在黑暗中擦肩而过的暧昧瞬间"]
      }
    ],
    "turning_point": "林聆无意中发现了沈默珍藏的旧照片，上面有他们两人的合影，但她完全不记得这段过去。"
  },
  "act_two": {
    "description": "冲突升级，林聆开始质疑现实，沈默的重生秘密逐渐显露，两人关系变得更加复杂",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "破碎的记忆",
        "core_event": "林聆开始出现闪回记忆片段，看到自己和沈默在不同场景中的画面。她质问沈默，但他只能用摩斯密码回避问题。",
        "emotional_tone": "混乱与不安",
        "key_scenes": ["林聆的闪回记忆片段", "沈默痛苦地拒绝回答", "录音棚外丧尸数量增加的危机"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第四面墙",
        "core_event": "林聆开始怀疑整个世界的真实性，觉得自己的经历像是被安排好的剧本。她尝试用摩斯密码反向询问，沈默被迫面对真相可能暴露的危险。",
        "emotional_tone": "哲学思辨与恐惧",
        "key_scenes": ["林聆对现实真实性的质疑", "沈默发现录音棚内出现异常现象", "两人在生死关头的深度交流"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "告白的线索",
        "core_event": "林聆偶然发现了录音笔，但无法播放。她感觉到里面藏着重要的秘密。同时，丧尸开始攻击录音棚的大门，情况危急。",
        "emotional_tone": "绝望中的希望",
        "key_scenes": ["林聆发现录音笔", "大门被丧尸撞击的紧张场面", "沈默决定采取极端措施保护她"]
      }
    ],
    "turning_point": "沈默终于决定告诉林聆部分真相，但在他行动前，录音棚的大门被彻底破坏。"
  },
  "act_three": {
    "description": "高潮对决，沈默选择牺牲自己引开尸群，林聆最终理解了一切，但为时已晚",
    "key_chapters": [
      {
        "chapter_number": 7,
        "chapter_title": "最后的选择",
        "core_event": "面对破门而入的丧尸，沈默做出了最终决定。他用摩斯密码最后一次指导林聆躲藏，然后准备开门引走尸群。",
        "emotional_tone": "悲壮与决绝",
        "key_scenes": ["沈默写下最后的告别信", "林聆通过地板震动感知他的行动", "沈默站在门口的最后回望"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "三年前的告白",
        "core_event": "在安全的藏身处，林聆终于找到了播放录音笔的方法。她听到了沈默三年前录制的告白，明白了所有真相，包括他的重生记忆和失声原因。",
        "emotional_tone": "撕心裂肺的领悟",
        "key_scenes": ["录音笔播放告白内容", "林联回忆起所有被遗忘的细节", "她意识到自己一直误解了摩斯密码的来源"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "命运的闭环",
        "core_event": "林聆独自在废墟中生存，带着沈默的录音笔。她开始用摩斯密码向虚空发送信息，仿佛在回应某种更高维度的存在，暗示命运的循环可能并未结束。",
        "emotional_tone": "绝望中的微光",
        "key_scenes": ["林聆在废墟中继续生存", "她用摩斯密码敲击金属的声音", "远处似乎有回应的节奏"]
      }
    ]
  }
}"}]

}

